import { Container, Separator } from '@/components/ui';
import BrandMark from '@/site/brand';
import { site } from '@/site/data';

export default function SiteFooter() {
  return (
    <footer className="bg-primary text-primary-foreground">
      <Container wide className="flex flex-col gap-10 py-14">
        <p className="max-w-3xl font-heading text-h3 text-balance">{site.description}</p>
        <div className="grid gap-8 border-t border-primary-foreground/20 pt-8 sm:grid-cols-2 lg:grid-cols-3">
          <nav aria-label="Pages" className="flex flex-col gap-2">
            {site.pages.map((page) => (<a key={page.href} className="text-small text-primary-foreground/85 hover:text-primary-foreground" href={page.href}>{page.label}</a>))}
          </nav>
          <div className="flex flex-col gap-2">
            {site.contact.channels.map((channel) => (channel.href ? <a key={channel.label} className="text-small text-primary-foreground/85 hover:text-primary-foreground" href={channel.href}>{channel.value}</a> : <span key={channel.label} className="text-small text-primary-foreground/85">{channel.value}</span>))}
          </div>
          <p className="text-small text-primary-foreground/70 lg:text-right">© {site.year} {site.name}</p>
        </div>
      </Container>
    </footer>
  );
}

