import { Menu } from 'lucide-react';
import { Button, Container, Sheet, SheetClose, SheetContent, SheetTitle, SheetTrigger } from '@/components/ui';
import BrandMark from '@/site/brand';
import LanguageSwitcher from '@/components/site/language-switcher';
import { site } from '@/site/data';
import { cn } from '@/lib/utils';

const isActive = (current: string, href: string) => current === href || current === `${href}/` || (href !== '/' && current.startsWith(href));

export default function SiteHeader({ current }: { current: string }) {
  return (
    <header className="sticky top-0 z-40 border-b border-border bg-background/95 backdrop-blur">
      <Container wide className="grid h-16 grid-cols-[1fr_auto_1fr] items-center gap-4">
        <div className="hidden md:block"><LanguageSwitcher current={current} /></div>
        <a href="/" className="col-start-2 flex items-center justify-center" aria-label={site.name}><BrandMark /></a>
        <div className="col-start-3 flex items-center justify-end gap-2">
          {site.primaryAction && <Button asChild size="sm" variant="outline" className="hidden md:inline-flex"><a href={site.primaryAction.href}>{site.primaryAction.label}</a></Button>}
          <Sheet>
            <SheetTrigger asChild>
              <Button size="icon" variant="ghost" className="md:hidden" aria-label="Menu"><Menu /></Button>
            </SheetTrigger>
            <SheetContent side="right" className="flex flex-col gap-6">
              <SheetTitle><BrandMark /></SheetTitle>
              <nav className="flex flex-col gap-1" aria-label="Menu">
                {site.navigation.map((item) => (
                  <SheetClose asChild key={item.href}>
                    <a href={item.href} aria-current={isActive(current, item.href) ? 'page' : undefined} className={cn('rounded-button px-3 py-2 text-body', isActive(current, item.href) ? 'bg-muted font-semibold text-foreground' : 'text-muted-foreground')}>{item.label}</a>
                  </SheetClose>
                ))}
              </nav>
              <LanguageSwitcher current={current} />
              {site.primaryAction && <Button asChild><a href={site.primaryAction.href}>{site.primaryAction.label}</a></Button>}
            </SheetContent>
          </Sheet>
        </div>
      </Container>
      <nav className="hidden border-t border-border md:block" aria-label="Menu">
        <Container wide className="flex h-11 items-center justify-center gap-6">
          {site.navigation.map((item) => (
            <a key={item.href} href={item.href} aria-current={isActive(current, item.href) ? 'page' : undefined} className={cn('text-small transition-colors hover:text-foreground', isActive(current, item.href) ? 'font-semibold text-foreground underline underline-offset-8 decoration-primary decoration-2' : 'text-muted-foreground')}>{item.label}</a>
          ))}
        </Container>
      </nav>
    </header>
  );
}

